import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';class CustomRadioOption extends StatelessWidget {  final String label;  final bool selected;  final VoidCallback onTap;  const CustomRadioOption({    super.key,    required this.label,    required this.selected,    required this.onTap,  });  @override  Widget build(BuildContext context) {    return GestureDetector(      onTap: onTap,      child: Container(        padding: EdgeInsets.symmetric(horizontal: 4.w, vertical: 1.5.h),        decoration: BoxDecoration(          color: selected ? Colors.blue.shade50 : Colors.white,          borderRadius: BorderRadius.circular(3.w),          border: Border.all(            color: selected ? Colors.blue : Colors.grey.shade300,            width: selected ? 1.2 : 0.7,          ),        ),        child: Row(          children: [            Container(              width: 4.w,              height: 4.w,              decoration: BoxDecoration(                shape: BoxShape.circle,                border: Border.all(                  color: selected ? Colors.blue : Colors.grey,                  width: 1,                ),              ),              child: selected                  ? Center(                child: Container(                  width: 2.w,                  height: 2.w,                  decoration: BoxDecoration(                    shape: BoxShape.circle,                    color: Colors.blue,                  ),                ),              )                  : const SizedBox.shrink(),            ),            SizedBox(width: 2.w),            Text(              label,              style: TextStyle(fontSize: 11.sp),            ),          ],        ),      ),    );  }}